# Buyer due-diligence checker. Uses our council data (CX) + nation rules; postcode lookup via postcodes.io (fetch only, no script).
import json as _j
_NR={n['id']:{r['topic']:r for r in n['rules']} for n in d['nations']}
def _nr(nid,*ts):
    for t in ts:
        if t in _NR.get(nid,{}):r=_NR[nid][t];return [r['text'],r['sources']]
    return None
_BN={}
for n in d['nations']:
    nid=n['id']
    _BN[nid]=dict(name=n['name'],rates=_nr(nid,'Non-domestic rates thresholds','Business rates vs council tax','182-day rule (rates)','Rates'),
        reg=_nr(nid,'Registration (WRA)','Registration scheme','Certification'))
_BC=[]
for c in d['councils']:
    s=slug(c)
    if s not in CX or not c['verified']:continue
    x=CX[s];f=lambda k:[x[k][0].replace('../',''),x[k][1]]
    _BC.append(dict(n=c['name'],s=s,nat=c['nation'].lower().replace(' ','-'),r=c['rule'],src=c['source'],lic=f('lic'),ctrl=f('ctrl'),levy=f('levy')))
GEN=[('Mortgage lender consent','Mortgage terms normally require you to ask the lender for consent before running a business from a property. Ask your lender or broker whether short-term letting is allowed on the product you plan to use. We make no claims about any lender.',['https://www.mygov.scot/home-based-business/before-you-start','https://www.mygov.scot/landlord-responsibilities']),
 ('Insurance','You need cover that suits short-term letting: holiday let insurance, public liability and buildings and contents cover. In Scotland, valid buildings insurance and public liability insurance for each let are mandatory licence conditions.',['https://www.gov.uk/guidance/letting-out-a-self-catering-holiday-home-in-england-rules-and-regulations','https://www.gov.scot/publications/short-term-lets-licensing-scheme-part-1-guidance-hosts-operators/pages/2/']),
 ('Lease, title deeds and owner consent','Check the title deeds (and the lease if the property is leasehold) for restrictions on running a business or letting, and get written consent where needed. In Scotland a licence application is refused without the consent of every owner.',['https://www.mygov.scot/home-based-business/before-you-start','https://www.gov.scot/publications/short-term-lets-licensing-scheme-part-1-guidance-hosts-operators/pages/2/']),
 ('Planning history','Ask your solicitor to confirm the property\'s lawful use and any planning permission or certificate for short-term letting, especially in a control area.',[]),
 ('Existing licence or registration','A licence or registration is usually personal to the operator or needs updating on a sale. Check with the council (Scotland) or the registration body before you rely on the seller\'s.',[])]
_opts=''.join(f'<option value="{c["s"]}">{e(c["n"])} ({e(c["nat"].replace("-"," ").title())})</option>' for c in sorted(_BC,key=lambda c:c['n']))
BJS='''<script>(function(){var C=__C__,N=__N__,G=__G__,$=function(i){return document.getElementById(i)};
function lk(s){return s&&s.length?' '+s.map(function(u){return '<a href="'+u+'" rel="nofollow">Source</a>'}).join(' '):''}
function nm(x){return x.toLowerCase().replace(/&/g,'and').replace(/^city of /,'').replace(/ city$/,'').replace(/[^a-z]/g,'')}
function sec(h,x){return x?'<div class="rc"><h3>'+h+'</h3><p>'+x[0]+lk(x[1])+'</p></div>':''}
function show(c){var n=N[c.nat]||{};$('br').innerHTML='<h2>'+c.n+'</h2><p class="lead">'+c.r+' <a href="'+c.src+'" rel="nofollow">Council source</a></p><div class="rcs">'+sec('Licence or registration',c.lic)+sec('Planning / control area',c.ctrl)+sec('Visitor levy',c.levy)+sec('Business rates or council tax (and second homes premium risk)',n.rates)+sec((n.name||'')+' registration or certification',n.reg)+'</div><p><a href="councils/'+c.s+'">Full '+c.n+' page</a> · <a href="occupancy-threshold-tracker.html">Occupancy threshold tracker</a></p><h2>Checks for every purchase</h2><div class="rcs">'+G.map(function(g){return sec(g[0],[g[1],g[2]])}).join('')+'</div><p class="small"><b>General information, not legal or financial advice.</b> Rules change: check the official sources and ask your solicitor. Data checked __D__.</p>';$('br').hidden=false;var A=$('by-alert'),F=$('by-form');if(A&&F){if(c.s=='perth-and-kinross'){A.hidden=true}else{F.setAttribute('data-area','council:'+c.s);F.setAttribute('data-area-name',c.n);$('by-an').textContent=c.n;$('by-why').textContent='We track licensing, planning, visitor levy and fee rules for '+c.n+' against official sources, and email you when one of them changes, so you hear about a new rule before or after you buy.';A.hidden=false;var hs=function(){var S=document.querySelector('section.alertcta');if(S)S.hidden=true};if(document.readyState=='loading')document.addEventListener('DOMContentLoaded',hs);else hs()}}$('br').focus()}
$('bgo').addEventListener('click',function(){var v=$('bc').value;for(var i=0;i<C.length;i++)if(C[i].s==v)return show(C[i])});
var q=(location.search.match(/[?&]council=([a-z0-9-]+)/)||[])[1];if(q)for(var i=0;i<C.length;i++)if(C[i].s==q){$('bc').value=q;show(C[i]);break}
$('bpgo').addEventListener('click',function(){var p=$('bp').value.replace(/\\s/g,'');$('bpm').textContent='Looking up...';
 fetch('https://api.postcodes.io/postcodes/'+encodeURIComponent(p)).then(function(r){return r.json()}).then(function(j){if(!j.result){$('bpm').textContent='Postcode not found. Pick the council instead.';return}
 var r=j.result,d=r.admin_district||'',k=nm(d),hit=null;
 for(var i=0;i<C.length;i++){if(nm(C[i].n)==k)hit=C[i]}
 if(!hit&&r.region=='London')for(var i=0;i<C.length;i++)if(C[i].n.indexOf('London')>=0)hit=C[i];
 if(hit){$('bpm').textContent=p.toUpperCase()+' is in '+d+'.';$('bc').value=hit.s;show(hit)}
 else{$('bpm').innerHTML=p.toUpperCase()+' is in '+d+' ('+(r.country||'')+'). We do not cover this council yet: see the <a href="'+((r.country||'').toLowerCase().replace(/ /g,'-'))+'">nation page</a> for national rules.'}
 }).catch(function(){$('bpm').textContent='Postcode lookup is unavailable. Pick the council instead.'})});
})();</script>'''.replace('__C__',_j.dumps(_BC)).replace('__N__',_j.dumps(_BN)).replace('__G__',_j.dumps(GEN)).replace('__D__',C)
# Common questions (visible + FAQPage JSON-LD). Built inline (guides.py shadows FAQ()). Re-checked 1 Nov 2026: gov.scot Part 1 guidance s.6.13-6.17 (transfer on sale) and s.2.21, 2.63;
# gov.scot short-term lets + mygov.scot control areas (updated 9 Oct 2025); legislation.gov.uk ukpga/2015/20 s.44; GOV.UK England self-catering (updated 2 Oct 2026) and England/Wales business rates pages;
# gov.wales WRA overview, Visitor Levy steps (Cardiff 1 Apr 2027, accounting from 28 Sep 2026; £1.30), use classes page + 30 Sep 2022 written statement; Eryri NPA Article 4 page (in force 1 Jun 2025);
# Gwynedd Article 4 page (quashed); mygov.scot self-catering rates (new owners, Example 1); MHCLG premium guidance; gov.scot news 31 Mar 2024; gov.wales premium guidance; mygov.scot home-based business.
BYQ=[('If I buy a short-term let in Scotland, does the seller\'s licence transfer to me?','Not automatically. A Scottish short-term let licence is specific to the licence holder (a person or a company) and the premises, so it cannot simply be handed over, even to someone who buys the property. If you want to keep letting, the seller can apply to the council to transfer the licence into your name. The council consults the Chief Constable on whether you are a fit and proper person, and there is no presumption that the transfer will be granted. If it is, the time left on the licence carries over to you (for example, a transfer 13 months into a 3-year licence means you renew after 23 more months). Otherwise you need your own licence before you take bookings or guests. Councils charge a transfer fee.'),
 ('Do I need planning permission to run a short-term let in Edinburgh or Badenoch and Strathspey?','Very likely, if it is a whole property that is not your main home. Scotland has two short-term let control areas: the whole City of Edinburgh (since 5 September 2022) and the Badenoch and Strathspey ward of Highland (since 4 March 2024). In a control area, using a dwelling that is not your main home as a short-term let very likely needs planning permission, and the licence application may need it. Elsewhere in Scotland, the planning authority decides whether letting is a material change of use. Proposed control areas only apply once they come into force, so check the council page in the checker above and ask the planning authority before you buy.'),
 ('Can I let a London property for more than 90 nights a year?','Not without planning permission. In Greater London, letting residential premises as short-term sleeping accommodation is not a material change of use only if two conditions are met: no more than 90 nights in the calendar year in total, and the person providing the accommodation is liable for council tax on the property for each of those nights. Above 90 nights you need planning permission from the borough. Nights from every platform and direct bookings count.'),
 ('Is there a licence or register for short-term lets in England?','Not yet. GOV.UK (updated 2 October 2026) says a mandatory national registration scheme for short-term lets in England is expected to begin in March 2027. No regulations, portal or fee have been published yet. Planning is decided locally: your local planning authority decides whether you need planning permission, based on how the property is used and its impact on neighbours and the area, so ask the council before you buy.'),
 ('What do I need to do when I buy a holiday let in Wales?','Register it with the Welsh Revenue Authority. If you take bookings of 31 nights or fewer and you are responsible for the accommodation (for example you own it), you must register by 31 March 2027, even if your council does not charge the visitor levy. Registration is free. A seller must update their own registration within 30 days if they sell. The visitor levy starts in Cardiff on 1 April 2027 at £1.30 per person per night for self-catering lets, and Cardiff providers must account for it on bookings from 28 September 2026. A national licensing scheme for self-catering lets is law but not in force yet (legal default March 2030).'),
 ('Do I need planning permission for a holiday let in Wales?','Usually not, unless an Article 4 direction applies. Since 2022 Wales has separate planning use classes for main homes (C3), second homes (C5) and short-term lets (C6), and changes between them are permitted development. A local planning authority can remove that right with an Article 4 direction. For example, Eryri National Park Authority\'s direction has been in force since 1 June 2025, while Cyngor Gwynedd\'s was quashed by the High Court and is not in force. Ask the planning authority for the property\'s area.'),
 ('Will the property pay business rates or council tax?','It depends on how it is let, so do not assume the seller\'s status carries on. England: available to let commercially for at least 140 nights and actually let for at least 70 nights in the last 12 months, and you intend to make it available for 140 nights in the next 12. Wales: at least 252 nights available and 182 nights let in 12 months, and you intend 252 in the next 12. Scotland: not anyone\'s only or main home, available for 140 nights and let for 70 nights in the financial year (1 April to 31 March), with evidence sent to the assessor by the deadline. A Scottish example on mygov.scot shows a buyer using letting evidence for the whole financial year they bought in, so ask the seller for booking records.'),
 ('What if it does not meet the business rates test?','It is charged council tax instead, and if nobody lives there as their main home it can count as a second home. Councils can charge a second homes premium on top: up to 100% extra in England (since 1 April 2025), up to double the full rate in Scotland (since 1 April 2024) and up to 300% extra in Wales (since 1 April 2023). Each council decides whether to charge it and at what rate, and there are exceptions, so check the council before you buy.'),
 ('What mortgage, insurance and title checks should I make?','Mortgage terms normally require you to ask the lender for consent before running a business from a property, so check that the product allows short-term letting. GOV.UK says short-term lets in England should have holiday let insurance, public liability cover, and buildings and contents cover suitable for short-term letting. In Scotland, valid buildings insurance and public liability insurance for each let are mandatory licence conditions. Ask your solicitor to check the title deeds (and the lease, if it is leasehold) for restrictions on letting or running a business. In Scotland a licence application is refused without the consent of every owner.')]
BYQLD=json.dumps({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in BYQ]}).replace('</','<\\/')
BYQH=('<h2 id="buyer-faq">Common questions</h2><div class="faq">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in BYQ)+'</div>'
 +'<p class="small">More detail: <a href="scotland-short-term-let-licence-guide">Scotland licence guide</a> · <a href="scotland-short-term-let-licence-fees">Licence fees, 32 councils</a> · <a href="london-90-night-counter">London 90-night counter</a> · <a href="england-short-term-let-rules-2027">England: what changes in 2027</a> · <a href="england-holiday-let-planning-permission">England planning permission</a> · <a href="wales-registration-checker">Wales registration checker</a> · <a href="occupancy-threshold-tracker">Occupancy threshold tracker</a> · <a href="england-second-homes-council-tax-premium">England second homes premium</a> · <a href="wales-second-homes-council-tax-premium">Wales second homes premium</a> · <a href="holiday-let-insurance-uk">Holiday let insurance</a>.</p>'
 +'<p class="small">Sources: <a href="https://www.gov.scot/publications/short-term-lets-licensing-scheme-part-1-guidance-hosts-operators/pages/6/" rel="nofollow">gov.scot Part 1 guidance, section 6 (selling your premises)</a>, <a href="https://www.gov.scot/publications/short-term-lets-licensing-scheme-part-1-guidance-hosts-operators/pages/2/" rel="nofollow">section 2 (owner consent, insurance)</a>, <a href="https://www.mygov.scot/short-term-let-licences/planning-permission-control-areas" rel="nofollow">mygov.scot: control areas</a>, <a href="https://www.gov.scot/publications/short-term-lets/" rel="nofollow">gov.scot: short-term lets</a>, <a href="https://www.legislation.gov.uk/ukpga/2015/20/section/44" rel="nofollow">Deregulation Act 2015, section 44</a>, <a href="https://www.gov.uk/guidance/letting-out-a-self-catering-holiday-home-in-england-rules-and-regulations" rel="nofollow">GOV.UK: self-catering in England</a>, <a href="https://www.gov.wales/registering-visitor-accommodation-overview" rel="nofollow">GOV.WALES: registering visitor accommodation</a>, <a href="https://www.gov.wales/check-if-local-council-charges-visitor-levy-wales" rel="nofollow">GOV.WALES: councils charging the levy</a>, <a href="https://www.gov.wales/planning-permission-use-classes-change-use" rel="nofollow">GOV.WALES: use classes</a>, <a href="https://planning.eryri.gov.wales/policy/article4/" rel="nofollow">Eryri National Park: Article 4 direction</a>, <a href="https://www.gwynedd.llyw.cymru/en-gb/planning-building-control-and-listed-buildings/planning/article-4-direction" rel="nofollow">Cyngor Gwynedd: Article 4 direction</a>, <a href="https://www.gov.uk/guidance/apply-for-business-rates-for-a-self-catering-property-in-england" rel="nofollow">GOV.UK: business rates, England</a>, <a href="https://www.gov.uk/guidance/apply-for-business-rates-for-a-self-catering-property-in-wales" rel="nofollow">GOV.UK: business rates, Wales</a>, <a href="https://www.legislation.gov.uk/wsi/2026/7/made" rel="nofollow">WSI 2026/7</a>, <a href="https://www.mygov.scot/non-domestic-rates-guidance/short-term-lets" rel="nofollow">mygov.scot: self-catering and non-domestic rates</a>, <a href="https://www.gov.uk/government/publications/long-term-empty-homes-and-second-homes-council-tax-premiums-and-exceptions/guidance-on-the-implementation-of-the-council-tax-premiums-on-long-term-empty-homes-and-second-homes" rel="nofollow">MHCLG: council tax premiums guidance</a>, <a href="https://www.gov.scot/news/council-tax-on-second-homes/" rel="nofollow">gov.scot: council tax on second homes</a>, <a href="https://www.gov.wales/council-tax-empty-and-second-homes-html" rel="nofollow">Welsh Government: council tax premiums</a>, <a href="https://www.mygov.scot/home-based-business/before-you-start" rel="nofollow">mygov.scot: before starting a home-based business</a>. Source: Welsh Government rules (WSI 2026/7). Checked 1 Nov 2026.</p>')
